SELECT *
FROM ai_conversations
WHERE conversation_id = #{conversationId}
  AND user_id         = #{userId}

SELECT c.conversation_id, c.scope, c.course_id, c.status, c.created_at, c.updated_at, (SELECT m.content FROM ai_messages m WHERE m.conversation_id = c.conversation_id AND m.role = 'USER' ORDER BY m.message_id ASC LIMIT 1) AS first_user_message, (SELECT MAX(m2.created_at) FROM ai_messages m2 WHERE m2.conversation_id = c.conversation_id) AS last_message_at, (SELECT COUNT(*) FROM ai_proposals p WHERE p.conversation_id = c.conversation_id AND p.status = 'PROPOSED') AS pending_proposal_count FROM ai_conversations c WHERE c.user_id = #{userId}
AND c.course_id = #{courseId}
AND c.course_id IS NULL
HAVING last_message_at IS NOT NULL ORDER BY last_message_at DESC

SELECT *
FROM ai_conversations
WHERE conversation_id = #{conversationId}
  AND user_id         = #{userId}
FOR UPDATE

mapper.update:
UPDATE ai_conversations
SET updated_at = CURRENT_TIMESTAMP
WHERE conversation_id = #{conversationId}
  AND user_id         = #{userId}

UPDATE ai_conversations
SET active_request_message_id = #{requestMessageId},
    active_request_started_at = CURRENT_TIMESTAMP
WHERE conversation_id = #{conversationId}
  AND user_id         = #{userId}

UPDATE ai_conversations
SET active_request_message_id = NULL,
    active_request_started_at = NULL
WHERE conversation_id           = #{conversationId}
  AND user_id                   = #{userId}
  AND active_request_message_id = #{requestMessageId}
